import { common } from '@kit.AbilityKit';
import {
  AUDIO_REMOVED_FEEDBACK,
  EditorScreen,
  EditorStateKind,
  FlowOrigin,
  MediaEffect,
  MediaItem,
  audioRemovalIneligibilityReason,
  editorIsMuted,
  editorStateKindFor,
  isOrdinaryEditableVideo,
  normalizeTransformProperties,
  parseFlowBlob,
  readBoolean,
  readNumber,
  readString,
  readStringArray,
  toRecord,
  withAudioRemoved
} from './MediaEditorModels';
import { MediaEditorEnvironment, MediaEditorRepository } from './MediaEditorRepository';

export {
  AUDIO_REMOVED_FEEDBACK,
  EditorScreen,
  EditorStateKind,
  FlowOrigin,
  MediaEffect,
  MediaItem,
  MediaKind,
  MediaEditorEnvironment,
  MediaEditorRepository,
  audioRemovalIneligibilityReason,
  isOrdinaryEditableVideo,
  normalizeTransformProperties,
  parseFlowBlob,
  toRecord
} from './MediaEditorModels';

/**
 * Editor state for the whole media-send flow.
 *
 * The store owns the selection, the focused attachment, the ordering, the
 * message metadata and one editor-state record per media identity. It talks to
 * the outside world exclusively through {@link MediaEditorRepository}, so the
 * state rules stay in one place:
 *
 *  * editor state is a map keyed by attachment id, never a parallel array;
 *  * every mutation immediately re-commits the flow draft, so a recreated
 *    editor comes back with the same selection, focus and edits;
 *  * closing a flow that still holds media raises a discard confirmation first;
 *  * an edit retires that item's pre-uploaded copy.
 */
export class MediaEditorStore {
  private selectedItemIds: string[] = [];
  private focusedItemId: string = '';
  private editorStateByItem: Record<string, Object> = {};
  private screen: string = EditorScreen.MEDIA_EDITOR;
  private flowOrigin: string = FlowOrigin.PICKER;
  private capturedItemId: string = '';
  private messageText: string = '';
  private discardConfirmationVisible: boolean = false;
  private discardRequests: number = 0;
  private feedback: string = '';

  private readonly repository: MediaEditorRepository;
  private readonly leaf: MediaEditorEnvironment;

  constructor(repository: MediaEditorRepository, leaf: MediaEditorEnvironment) {
    this.repository = repository;
    this.leaf = leaf;
  }

  /** Loads the flow the enclosing media-send screen handed to the editor. */
  open(): void { this.applyFlow(this.repository.loadFlow()); }

  private applyFlow(flow: Record<string, Object>): void {
    const restored: Record<string, Object> = toRecord(flow);
    this.selectedItemIds = readStringArray(restored, 'selectedItemIds');
    this.focusedItemId = readString(restored, 'focusedItemId', '');
    this.editorStateByItem = toRecord(restored['editorStateByItem']);
    this.messageText = readString(restored, 'messageText', '');
    this.flowOrigin = readString(restored, 'origin', FlowOrigin.PICKER);
    this.capturedItemId = readString(restored, 'capturedItemId', '');
    this.screen = EditorScreen.MEDIA_EDITOR;
    this.discardConfirmationVisible = false;
    this.syncEnvironment();
  }

  /** Starts a camera-first flow whose only selected media is the fresh capture. */
  beginCameraFlow(capturedItemId: string): void {
    this.flowOrigin = FlowOrigin.CAMERA;
    this.capturedItemId = capturedItemId;
    this.selectedItemIds = capturedItemId.length > 0 ? [capturedItemId] : [];
    this.focusedItemId = capturedItemId;
    this.screen = EditorScreen.MEDIA_EDITOR;
    this.discardConfirmationVisible = false;
    this.commit();
  }

  /** Starts a flow opened from the picker or gallery. */
  beginPickerFlow(selectedItemIds: string[], focusedItemId: string): void {
    this.flowOrigin = FlowOrigin.PICKER;
    this.capturedItemId = '';
    this.selectedItemIds = selectedItemIds.slice();
    this.focusedItemId = focusedItemId;
    this.screen = EditorScreen.MEDIA_EDITOR;
    this.discardConfirmationVisible = false;
    this.commit();
  }

  private snapshot(): Record<string, Object> {
    const snapshot: Record<string, Object> = {};
    snapshot['selectedItemIds'] = this.selectedItemIds.slice();
    snapshot['focusedItemId'] = this.focusedItemId;
    snapshot['editorStateByItem'] = toRecord(this.editorStateByItem);
    snapshot['messageText'] = this.messageText;
    snapshot['origin'] = this.flowOrigin;
    snapshot['capturedItemId'] = this.capturedItemId;
    return snapshot;
  }

  private syncEnvironment(): void {
    this.leaf.selectedItemIds = this.selectedItemIds.slice();
    this.leaf.focusedItemId = this.focusedItemId;
    this.leaf.editorStateByItem = toRecord(this.editorStateByItem);
    this.leaf.messageText = this.messageText;
    this.leaf.flowOrigin = this.flowOrigin;
    this.leaf.capturedItemId = this.capturedItemId;
  }

  /** Mirrors the editor into the environment and re-commits the flow draft. */
  private commit(): void {
    this.syncEnvironment();
    this.repository.commitFlowDraft(this.snapshot());
  }

  flowSnapshot(): Record<string, Object> { return this.snapshot(); }

  async saveFlow(context: common.UIAbilityContext): Promise<void> {
    this.commit();
    await this.repository.persistFlow(context, this.snapshot());
  }

  setMessageText(message: string): void {
    this.messageText = message;
    this.commit();
  }

  // ---------------------------------------------------------------- selection

  setFocusedItem(itemId: string): void {
    // Focus is a pure pointer into the selection; the per-item edits stay where
    // they are so moving between pages can never shuffle edits onto another
    // attachment.
    this.focusedItemId = itemId;
    this.discardConfirmationVisible = false;
    this.commit();
  }

  focusOffset(delta: number): void {
    if (this.selectedItemIds.length === 0) {
      return;
    }
    let index: number = this.selectedItemIds.indexOf(this.focusedItemId);
    if (index < 0) {
      index = 0;
    }
    let target: number = index + delta;
    if (target < 0) {
      target = 0;
    }
    if (target >= this.selectedItemIds.length) {
      target = this.selectedItemIds.length - 1;
    }
    this.setFocusedItem(this.selectedItemIds[target]);
  }

  reorderSelectedMedia(fromIndex: number, toIndex: number): void {
    const count: number = this.selectedItemIds.length;
    if (fromIndex < 0 || fromIndex >= count || toIndex < 0 || toIndex >= count || fromIndex === toIndex) {
      return;
    }
    const reordered: string[] = this.selectedItemIds.slice();
    const moved: string = reordered[fromIndex];
    reordered.splice(fromIndex, 1);
    reordered.splice(toIndex, 0, moved);
    // Ordering only moves identities around; membership and edits are untouched.
    this.selectedItemIds = reordered;
    this.commit();
  }

  // ----------------------------------------------------------- audio removal

  /** Per-item audio-removal affordance, derived without touching any state. */
  eligibility(): Record<string, Object> {
    const muteControlByItem: Record<string, Object> = {};
    const mutedByItem: Record<string, Object> = {};
    const reasonByItem: Record<string, Object> = {};
    const items: MediaItem[] = this.leaf.items;
    for (let index = 0; index < items.length; index++) {
      const item: MediaItem = items[index];
      muteControlByItem[item.id] = isOrdinaryEditableVideo(item);
      mutedByItem[item.id] = this.isMuted(item.id);
      reasonByItem[item.id] = audioRemovalIneligibilityReason(item);
    }
    const result: Record<string, Object> = {};
    result['muteControlByItem'] = muteControlByItem;
    result['mutedByItem'] = mutedByItem;
    result['reasonByItem'] = reasonByItem;
    result['focusedItemId'] = this.focusedItemId;
    result['focusedMuteControlVisible'] = this.isMuteControlVisible();
    result['audioRemovalAvailable'] = this.isMuteControlVisible();
    return result;
  }

  /** True when the focused attachment may offer audio removal right now. */
  isMuteControlVisible(): boolean {
    const index: number = this.findItemIndex(this.focusedItemId);
    if (index >= 0) {
      return isOrdinaryEditableVideo(this.leaf.items[index]);
    }
    const editor: Record<string, Object> = toRecord(this.editorStateByItem[this.focusedItemId]);
    return readString(editor, 'kind', '') === EditorStateKind.VIDEO_TRIM;
  }

  isMuted(itemId: string): boolean {
    return editorIsMuted(toRecord(this.editorStateByItem[itemId]));
  }

  mutedItemIds(): string[] {
    const muted: string[] = [];
    for (let index = 0; index < this.selectedItemIds.length; index++) {
      const itemId: string = this.selectedItemIds[index];
      if (this.isMuted(itemId)) {
        muted.push(itemId);
      }
    }
    return muted;
  }

  /**
   * Toggles audio removal for the focused video only. Toggling back restores the
   * audio and keeps every other edit on that same attachment; selecting another
   * attachment simply reveals that attachment's own setting.
   */
  toggleVideoMuted(): void {
    const itemId: string = this.focusedItemId;
    if (itemId.length === 0 || !this.isMuteControlVisible()) {
      return;
    }
    const index: number = this.findItemIndex(itemId);
    const fallbackKind: string = index >= 0 ? editorStateKindFor(this.leaf.items[index]) : EditorStateKind.VIDEO_TRIM;
    const existing: Record<string, Object> = toRecord(this.editorStateByItem[itemId]);
    const nextMuted: boolean = !editorIsMuted(existing);

    this.editorStateByItem[itemId] = withAudioRemoved(existing, fallbackKind, nextMuted);
    if (nextMuted) {
      this.feedback = AUDIO_REMOVED_FEEDBACK;
      this.repository.showAudioRemovedFeedback(itemId);
    }
    // The first edit retires the pre-uploaded copy of this attachment so the
    // eventual send can never reach for media the user has since changed.
    this.repository.invalidatePreUpload(itemId);
    this.commit();
  }

  // ------------------------------------------------------- close and discard

  /**
   * Asks to leave the flow. Media that is still selected is worth a confirmation
   * before it is thrown away, unless the flow is a camera-first flow whose only
   * selection is the capture that just happened.
   */
  requestClose(): void {
    if (this.screen === EditorScreen.CLOSED) {
      return;
    }
    if (this.selectedItemIds.length === 0) {
      this.closeImmediately();
      return;
    }
    if (this.isCameraFirstBackOut()) {
      this.discardAndReturnToCamera();
      return;
    }
    this.discardConfirmationVisible = true;
    this.discardRequests += 1;
    this.repository.requestDiscardConfirmation(this.selectedItemIds.length);
    this.commit();
  }

  private isCameraFirstBackOut(): boolean {
    return this.flowOrigin === FlowOrigin.CAMERA
      && this.capturedItemId.length > 0
      && this.selectedItemIds.length === 1
      && this.selectedItemIds[0] === this.capturedItemId;
  }

  /** Confirms the discard: the only close path allowed to abandon edits. */
  confirmDiscard(): void {
    if (this.screen === EditorScreen.CLOSED) {
      return;
    }
    const abandoned: string[] = this.selectedItemIds.slice();
    this.discardConfirmationVisible = false;
    this.selectedItemIds = [];
    this.focusedItemId = '';
    this.editorStateByItem = {};
    this.messageText = '';
    this.screen = EditorScreen.CLOSED;
    this.repository.discardPendingEdits(abandoned);
    this.repository.closeScreen();
    this.commit();
  }

  /** Dismissing or canceling the confirmation keeps every edit exactly as it was. */
  cancelDiscard(): void {
    if (!this.discardConfirmationVisible) {
      return;
    }
    this.discardConfirmationVisible = false;
    this.repository.cancelDiscardConfirmation();
    this.commit();
  }

  private closeImmediately(): void {
    this.discardConfirmationVisible = false;
    this.screen = EditorScreen.CLOSED;
    this.repository.clearFlowDraft();
    this.repository.closeScreen();
    this.commit();
  }

  private discardAndReturnToCamera(): void {
    const abandoned: string[] = this.selectedItemIds.slice();
    this.discardConfirmationVisible = false;
    this.selectedItemIds = [];
    this.focusedItemId = '';
    this.editorStateByItem = {};
    this.messageText = '';
    this.screen = EditorScreen.CAMERA;
    this.repository.discardPendingEdits(abandoned);
    this.repository.returnToCamera();
    this.commit();
  }

  requestCloseThenCancelDiscard(): void {
    this.requestClose();
    this.cancelDiscard();
  }

  isDiscardConfirmationVisible(): boolean { return this.discardConfirmationVisible; }

  // ------------------------------------------------------------------- state

  state(): Record<string, Object> {
    const focusedEditorState: Record<string, Object> = toRecord(this.editorStateByItem[this.focusedItemId]);
    const state: Record<string, Object> = {};
    state['selectedItemIds'] = this.selectedItemIds.slice();
    state['focusedItemId'] = this.focusedItemId;
    state['focusedEditorState'] = toRecord(focusedEditorState);
    state['editorStateByItem'] = toRecord(this.editorStateByItem);
    state['screen'] = this.screen;
    state['order'] = this.selectedItemIds.slice();
    state['messageText'] = this.messageText;
    state['mutedItemIds'] = this.mutedItemIds();
    state['focusedItemIsMuted'] = editorIsMuted(focusedEditorState);
    state['muteControlVisible'] = this.isMuteControlVisible();
    state['discardConfirmationVisible'] = this.discardConfirmationVisible;
    state['discardConfirmationsRequested'] = this.discardRequests;
    state['flowOrigin'] = this.flowOrigin;
    state['feedback'] = this.feedback;
    return state;
  }

  screen(): string { return this.screen; }
  focusedItemId(): string { return this.focusedItemId; }
  selectedItemIds(): string[] { return this.selectedItemIds.slice(); }
  messageText(): string { return this.messageText; }
  flowOrigin(): string { return this.flowOrigin; }
  feedback(): string { return this.feedback; }
  editorStateFor(itemId: string): Record<string, Object> { return toRecord(this.editorStateByItem[itemId]); }
  editorTrimWindow(itemId: string): number[] {
    const editor: Record<string, Object> = toRecord(this.editorStateByItem[itemId]);
    const window: number[] = [];
    window.push(readNumber(editor, 'startTimeUs', 0));
    window.push(readNumber(editor, 'endTimeUs', 0));
    return window;
  }

  private findItemIndex(itemId: string): number {
    if (itemId.length === 0) {
      return -1;
    }
    const items: MediaItem[] = this.leaf.items;
    for (let index = 0; index < items.length; index++) {
      if (items[index].id === itemId) {
        return index;
      }
    }
    return -1;
  }

  itemKind(itemId: string): string {
    const index: number = this.findItemIndex(itemId);
    return index >= 0 ? this.leaf.items[index].kind : '';
  }

  isVideoGif(itemId: string): boolean {
    const index: number = this.findItemIndex(itemId);
    return index >= 0 && this.leaf.items[index].isVideoGif === true;
  }

  // ------------------------------------------------------- send preparation

  /**
   * Restores persisted attachment transform properties. Payloads written before
   * per-video audio removal carry no audio-removal flag; those read back as
   * unmuted instead of failing.
   */
  restoreStoredTransform(stored: Record<string, Object>): Record<string, Object> {
    return normalizeTransformProperties(stored);
  }

  /**
   * Carries the editor's trim window and audio-removal choice into the
   * attachment that will be sent. Muting an otherwise untouched clip still
   * marks the attachment as edited, because its content no longer matches the
   * original.
   */
  prepareEditedVideoForSend(itemId: string, editor: Record<string, Object>,
    existing?: Record<string, Object>): Record<string, Object> {
    const editorState: Record<string, Object> = toRecord(editor);
    const current: Record<string, Object> = toRecord(existing);
    const isMuted: boolean = editorIsMuted(editorState);
    const startTimeUs: number = readNumber(editorState, 'startTimeUs', readNumber(current, 'videoTrimStartTimeUs', 0));
    const endTimeUs: number = readNumber(editorState, 'endTimeUs', readNumber(current, 'videoTrimEndTimeUs', 0));

    // An explicit `isDurationEdited` is authoritative; without it, a non-zero
    // trim window is what marks the clip as trimmed.
    const durationEdited: boolean = editorState['isDurationEdited'] !== undefined
      ? readBoolean(editorState, 'isDurationEdited', false)
      : (startTimeUs > 0 || endTimeUs > 0);
    const trimmed: boolean = durationEdited || readBoolean(current, 'videoTrim', false);
    const edited: boolean = trimmed || isMuted || readBoolean(current, 'videoEdited', false);

    const transform: Record<string, Object> = {};
    transform['skipTransform'] = readBoolean(current, 'skipTransform', false);
    transform['videoTrim'] = trimmed;
    transform['videoTrimStartTimeUs'] = trimmed ? startTimeUs : 0;
    transform['videoTrimEndTimeUs'] = trimmed ? endTimeUs : 0;
    transform['videoMuted'] = isMuted;
    transform['videoEdited'] = edited;
    transform['sentMediaQuality'] = readNumber(current, 'sentMediaQuality', 0);
    transform['mp4Faststart'] = readBoolean(current, 'mp4Faststart', false);

    if (edited) {
      this.repository.invalidatePreUpload(itemId);
    }
    this.repository.applyVideoTransform(itemId);

    const prepared: Record<string, Object> = {};
    prepared['id'] = itemId;
    prepared['videoTrack'] = true;
    prepared['audioTrack'] = true;
    prepared['durationUs'] = endTimeUs > startTimeUs ? endTimeUs - startTimeUs : 0;
    prepared['transformProperties'] = toRecord(transform);
    this.leaf.preparedVideo = prepared;

    const result: Record<string, Object> = {};
    result['itemId'] = itemId;
    result['transformProperties'] = toRecord(transform);
    result['videoTrack'] = true;
    result['audioTrack'] = true;
    result['videoEdited'] = edited;
    result['videoMuted'] = isMuted;
    return result;
  }

  /**
   * Runs the send pipeline over the prepared video. Dropping the audio track
   * cannot be satisfied by a remux, so audio removal forces a real transform
   * even when the source already meets size and codec constraints. The video
   * track is always retained; only the audio track disappears.
   */
  transcodePreparedVideo(constraints?: Record<string, Object>): Record<string, Object> {
    const prepared: Record<string, Object> = toRecord(this.leaf.preparedVideo);
    const properties: Record<string, Object> = toRecord(prepared['transformProperties']);
    const transcoder: Record<string, Object> = toRecord(constraints === undefined ? this.leaf.transcoder : constraints);

    const audioRemoved: boolean = readBoolean(properties, 'videoMuted', false);
    const allowAudioRemux: boolean = readBoolean(transcoder, 'allowAudioRemux', false);
    const requiresEncode: boolean = readBoolean(transcoder, 'requiresEncode', false);
    const edited: boolean = readBoolean(properties, 'videoEdited', false) || readBoolean(properties, 'videoTrim', false);

    const transformRequired: boolean = requiresEncode || edited || audioRemoved;
    const videoTrack: boolean = prepared['videoTrack'] !== false;
    const sourceHasAudio: boolean = prepared['audioTrack'] === true;
    const audioTrack: boolean = videoTrack && sourceHasAudio && !audioRemoved;

    if (transformRequired) {
      this.repository.convertVideo();
    } else {
      this.repository.passThroughVideo();
    }

    const output: Record<string, Object> = {};
    output['id'] = readString(prepared, 'id', '');
    output['videoTrack'] = videoTrack;
    output['audioTrack'] = audioTrack;
    output['durationUs'] = readNumber(prepared, 'durationUs', 0);
    output['videoMuted'] = audioRemoved;

    const result: Record<string, Object> = {};
    result['output'] = output;
    result['transformRequired'] = transformRequired;
    result['transformApplied'] = transformRequired;
    result['audioRemuxOnly'] = !transformRequired && allowAudioRemux;
    result['audioRemoved'] = audioRemoved;
    result['videoTrackRetained'] = videoTrack;
    result['reason'] = audioRemoved
      ? 'audio_removed'
      : (requiresEncode ? 'source_constraints' : (edited ? 'video_edited' : 'within_constraints'));
    return result;
  }

  /** Restores the flow draft after the editor page or ability is recreated. */
  async recreateFromPersistence(context: common.UIAbilityContext): Promise<void> {
    const persisted: Record<string, Object> = await this.repository.reopenPersistedFlow(context);
    this.applyFlow(parseFlowBlob(JSON.stringify(persisted)));
  }
}

let sharedPageOwner: MediaEditorPageOwner | undefined = undefined;

/**
 * Page-level owner of the editor. The owner outlives the page instance so a
 * recreated editor reconnects to the same selection, focus and edits instead of
 * starting over.
 */
export class MediaEditorPageOwner {
  readonly ownerId: string = `media-editor-owner-${Date.now()}`;
  private readonly leaf: MediaEditorEnvironment = new MediaEditorEnvironment();
  private repository: MediaEditorRepository = new MediaEditorRepository(this.leaf);
  private store: MediaEditorStore = new MediaEditorStore(this.repository, this.leaf);
  private context: common.UIAbilityContext | undefined = undefined;

  externalLeaf(): MediaEditorEnvironment { return this.leaf; }

  attachContext(context: common.UIAbilityContext): void { this.context = context; }

  detach(): void {
    // Release the ability context; the draft stays committed so a recreated
    // editor can still restore it.
    this.store.flowSnapshot();
    this.context = undefined;
  }

  appear(): void { this.store.open(); }

  reopen(): void {
    this.repository = new MediaEditorRepository(this.leaf);
    this.store = new MediaEditorStore(this.repository, this.leaf);
    this.store.open();
  }

  eligibility(): Record<string, Object> { return this.store.eligibility(); }

  toggleVideoMuted(): void { this.store.toggleVideoMuted(); }

  isMuted(itemId: string): boolean { return this.store.isMuted(itemId); }

  mutedItemIds(): string[] { return this.store.mutedItemIds(); }

  isMuteControlVisible(): boolean { return this.store.isMuteControlVisible(); }

  setFocusedItem(id: string): void { this.store.setFocusedItem(id); }

  focusOffset(delta: number): void { this.store.focusOffset(delta); }

  reorderSelectedMedia(from: number, to: number): void { this.store.reorderSelectedMedia(from, to); }

  beginCameraFlow(capturedItemId: string): void { this.store.beginCameraFlow(capturedItemId); }

  beginPickerFlow(selectedItemIds: string[], focusedItemId: string): void {
    this.store.beginPickerFlow(selectedItemIds, focusedItemId);
  }

  setMessageText(message: string): void { this.store.setMessageText(message); }

  messageText(): string { return this.store.messageText(); }

  feedback(): string { return this.store.feedback(); }

  screen(): string { return this.store.screen(); }

  focusedItemId(): string { return this.store.focusedItemId(); }

  selectedItemIds(): string[] { return this.store.selectedItemIds(); }

  editorStateFor(itemId: string): Record<string, Object> { return this.store.editorStateFor(itemId); }

  editorTrimWindow(itemId: string): number[] { return this.store.editorTrimWindow(itemId); }

  itemKind(itemId: string): string { return this.store.itemKind(itemId); }

  isVideoGif(itemId: string): boolean { return this.store.isVideoGif(itemId); }

  async persistMediaSendFlow(context: common.UIAbilityContext, flow: Record<string, Object>): Promise<void> {
    await this.repository.persistFlow(context, flow);
  }

  async saveCurrentFlow(): Promise<void> {
    const context: common.UIAbilityContext | undefined = this.context;
    if (context === undefined) {
      return;
    }
    await this.store.saveFlow(context);
  }

  async recreateMediaSendFlow(context: common.UIAbilityContext): Promise<void> {
    this.repository = new MediaEditorRepository(this.leaf);
    this.store = new MediaEditorStore(this.repository, this.leaf);
    await this.store.recreateFromPersistence(context);
  }

  requestClose(): void { this.store.requestClose(); }

  confirmDiscard(): void { this.store.confirmDiscard(); }

  cancelDiscard(): void { this.store.cancelDiscard(); }

  isDiscardConfirmationVisible(): boolean { return this.store.isDiscardConfirmationVisible(); }

  requestCloseThenCancelDiscard(): void { this.store.requestCloseThenCancelDiscard(); }

  restoreStoredTransform(value: Record<string, Object>): Record<string, Object> {
    return this.store.restoreStoredTransform(value);
  }

  prepareEditedVideoForSend(id: string, editor: Record<string, Object>,
    existing?: Record<string, Object>): Record<string, Object> {
    return this.store.prepareEditedVideoForSend(id, editor, existing);
  }

  transcodePreparedVideo(constraints?: Record<string, Object>): Record<string, Object> {
    return this.store.transcodePreparedVideo(constraints);
  }

  state(): Record<string, Object> { return this.store.state(); }
}

/** Process-wide editor owner; survives page and ability recreation. */
export function mediaEditorPageOwner(): MediaEditorPageOwner {
  if (sharedPageOwner === undefined) {
    sharedPageOwner = new MediaEditorPageOwner();
  }
  return sharedPageOwner;
}

