import { promptAction } from '@kit.ArkUI';
import { MediaEditorPageOwner, EditorScreen, mediaEditorPageOwner } from '../feature/MediaEditorStore';

/**
 * Media editor screen.
 *
 * The page is a thin projection of {@link MediaEditorPageOwner}: it re-reads the
 * editor state into `@State` fields after every interaction so ArkUI re-renders,
 * and it never keeps a copy of an edit of its own. That keeps selection, focus,
 * ordering, message metadata and per-item edits owned by the editor where they
 * are keyed by media identity.
 */
@Entry
@Component
struct Index {
  private owner: MediaEditorPageOwner = mediaEditorPageOwner();

  @State private selectedIds: string[] = [];
  @State private focusedId: string = '';
  @State private screenLabel: string = EditorScreen.MEDIA_EDITOR;
  @State private mutedIds: string[] = [];
  @State private muteControlVisible: boolean = false;
  @State private focusedMuted: boolean = false;
  @State private discardPending: boolean = false;
  @State private composerText: string = '';
  @State private feedback: string = '';
  @State private breakpoint: string = 'sm';

  aboutToAppear(): void {
    this.owner.appear();
    this.reload();
  }

  aboutToDisappear(): void {
    this.owner.detach();
  }

  onBackPress(): boolean {
    this.attemptClose();
    return true;
  }

  private reload(): void {
    this.selectedIds = this.owner.selectedItemIds();
    this.focusedId = this.owner.focusedItemId();
    this.screenLabel = this.owner.screen();
    this.mutedIds = this.owner.mutedItemIds();
    this.muteControlVisible = this.owner.isMuteControlVisible();
    this.focusedMuted = this.owner.isMuted(this.focusedId);
    this.discardPending = this.owner.isDiscardConfirmationVisible();
    this.composerText = this.owner.messageText();
    this.feedback = this.owner.feedback();
  }

  private columnCount(): number {
    return this.breakpoint === 'lg' || this.breakpoint === 'xl' || this.breakpoint === 'xxl' ? 2 : 1;
  }

  private isMuted(itemId: string): boolean {
    return this.mutedIds.indexOf(itemId) >= 0;
  }

  private labelFor(itemId: string): string {
    const kind: string = this.owner.itemKind(itemId);
    const muted: boolean = this.isMuted(itemId);
    let label: string = itemId;
    if (this.owner.isVideoGif(itemId)) {
      label = `${itemId} (GIF)`;
    } else if (kind === 'video') {
      label = muted ? `${itemId} - audio removed` : itemId;
    }
    return label;
  }

  private focusedTrimWindow(): string {
    if (this.focusedId.length === 0) {
      return '';
    }
    const window: number[] = this.owner.editorTrimWindow(this.focusedId);
    if (window.length < 2 || (window[0] === 0 && window[1] === 0)) {
      return '';
    }
    return `Trim ${window[0]}us - ${window[1]}us`;
  }

  private onToggleMute(): void {
    this.owner.toggleVideoMuted();
    this.reload();
    if (this.feedback.length > 0) {
      promptAction.showToast({ message: this.feedback });
    }
    this.persistDraft();
  }

  private onFocus(itemId: string): void {
    this.owner.setFocusedItem(itemId);
    this.reload();
    this.persistDraft();
  }

  private onReorder(from: number, to: number): void {
    this.owner.reorderSelectedMedia(from, to);
    this.reload();
    this.persistDraft();
  }

  private onMessageChanged(value: string): void {
    this.composerText = value;
    this.owner.setMessageText(value);
  }

  private persistDraft(): void {
    this.owner.saveCurrentFlow();
  }

  private attemptClose(): void {
    this.owner.requestClose();
    this.reload();
    if (!this.discardPending) {
      return;
    }
    this.getUIContext().showAlertDialog({
      title: 'Discard media?',
      message: 'This message still has media and edits attached.',
      autoCancel: true,
      primaryButton: {
        value: 'Discard',
        action: (): void => {
          this.owner.confirmDiscard();
          this.reload();
        }
      },
      secondaryButton: {
        value: 'Keep editing',
        action: (): void => {
          this.owner.cancelDiscard();
          this.reload();
        }
      }
    });
  }

  @Builder
  MediaStrip() {
    Column({ space: 8 }) {
      Text('Selected media')
        .fontSize(16)
        .fontWeight(FontWeight.Medium)
      if (this.selectedIds.length === 0) {
        Text('No media selected')
          .fontSize(14)
          .fontColor(Color.Gray)
      } else {
        List({ space: 8 }) {
          ForEach(this.selectedIds, (itemId: string) => {
            ListItem() {
              Row({ space: 12 }) {
                Text(`${this.selectedIds.indexOf(itemId) + 1}`)
                  .fontSize(12)
                  .fontColor(Color.Gray)
                  .width(24)
                Text(this.labelFor(itemId))
                  .fontSize(15)
                  .fontWeight(this.focusedId === itemId ? FontWeight.Bold : FontWeight.Normal)
                  .layoutWeight(1)
                Text(this.focusedId === itemId ? 'focused' : '')
                  .fontSize(12)
                  .fontColor(Color.Blue)
              }
              .width('100%')
              .padding(10)
              .borderRadius(8)
              .backgroundColor(this.focusedId === itemId ? '#110000ff' : '#f2f2f2')
              .onClick(() => {
                this.onFocus(itemId);
              })
            }
          }, (itemId: string) => itemId)
        }
        .width('100%')
        .layoutWeight(1)
      }
    }
    .width('100%')
  }

  @Builder
  EditorControls() {
    Column({ space: 12 }) {
      Text(this.screenLabel === EditorScreen.MEDIA_EDITOR ? 'Media editor' : `Screen: ${this.screenLabel}`)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)

      Text(`Focused: ${this.focusedId.length > 0 ? this.focusedId : 'none'}`)
        .fontSize(14)
        .id('focused-media')

      Text(this.focusedTrimWindow())
        .fontSize(12)
        .fontColor(Color.Gray)

      Row({ space: 10 }) {
        Button(this.focusedMuted ? 'Restore audio' : 'Remove audio')
          .id('toggle-audio')
          .enabled(this.muteControlVisible)
          .visibility(this.muteControlVisible ? Visibility.Visible : Visibility.None)
          .onClick(() => {
            this.onToggleMute();
          })
        Button('Next media')
          .id('next-media')
          .onClick(() => {
            this.owner.focusOffset(1);
            this.reload();
            this.persistDraft();
          })
        Button('Prev media')
          .id('prev-media')
          .onClick(() => {
            this.owner.focusOffset(-1);
            this.reload();
            this.persistDraft();
          })
      }

      if (!this.muteControlVisible && this.focusedId.length > 0) {
        Text('Audio removal is not available for this item')
          .fontSize(12)
          .fontColor(Color.Gray)
      }

      Row({ space: 10 }) {
        Button('Move')
          .id('reorder-media')
          .enabled(this.selectedIds.length > 1)
          .onClick(() => {
            const last: number = this.selectedIds.length - 1;
            const from: number = this.selectedIds.indexOf(this.focusedId);
            this.onReorder(from < 0 ? 0 : from, from === last ? 0 : from + 1);
          })
        Button('Close')
          .id('close-editor')
          .onClick(() => {
            this.attemptClose();
          })
      }

      TextInput({ text: this.composerText, placeholder: 'Add a message' })
        .id('message-input')
        .onChange((value: string) => {
          this.onMessageChanged(value);
        })

      Text(this.feedback)
        .fontSize(12)
        .fontColor(Color.Green)
        .id('editor-feedback')

      Text(`Screen: ${this.screenLabel}`)
        .fontSize(12)
        .id('editor-screen')
    }
    .width('100%')
    .alignItems(HorizontalAlign.Start)
  }

  build() {
    GridRow({
      columns: this.columnCount(),
      gutter: 16,
      breakpoints: {
        value: ['320vp', '600vp', '840vp'],
        reference: BreakpointsReference.WindowSize
      }
    }) {
      GridCol({ span: 1 }) {
        this.MediaStrip()
      }
      GridCol({ span: 1 }) {
        this.EditorControls()
      }
    }
    .width('100%')
    .height('100%')
    .padding(16)
    .alignItems(VerticalAlign.Top)
    .onBreakpointChange((points: string) => {
      this.breakpoint = points;
    })
  }
}

import { AbilityConstant, BusinessError, UIAbility, Want } from '@kit.AbilityKit';
import { window } from '@kit.ArkUI';
import { mediaEditorPageOwner } from '../feature/MediaEditorStore';

export default class EntryAbility extends UIAbility {
  onCreate(want: Want, launchParam: AbilityConstant.LaunchParam): void {
    // The editor owner is process-wide, so binding the ability context here lets
    // a recreated editor page keep persisting the same media-send flow.
    mediaEditorPageOwner().attachContext(this.context);
  }

  onWindowStageCreate(windowStage: window.WindowStage): void {
    windowStage.loadContent('pages/Index', (error: BusinessError): void => {
      if (error.code) {
        console.error(`[media-editor] failed to load pages/Index: ${error.code} ${error.message}`);
      }
    });
  }

  onWindowStageDestroy(): void {
    mediaEditorPageOwner().saveCurrentFlow();
  }

  onDestroy(): void {
    mediaEditorPageOwner().detach();
  }
}

