/** Restores the flow draft after the editor page or ability is recreated. */
  async recreateFromPersistence(context: common.UIAbilityContext): Promise<void> {
    const persisted: Record<string, Object> = await this.repository.reopenPersistedFlow(context);
    if (isEmptyFlow(persisted)) {
      // Nothing durable came back. The mirrored flow is still valid, so keep it
      // rather than silently resetting a flow the user never abandoned.
      this.applyFlow(this.repository.loadFlow());
      return;
    }
    this.applyFlow(parseFlowBlob(JSON.stringify(persisted)));
  }

